mapper.sql:
SELECT s.event_id, s.tenant_id, s.user_id, s.api_key_id, s.service_id, s.source, s.operation,
       s.request_id, s.request_started_at, s.cost_status, s.estimated_cost_fen AS cost_fen,
       s.budget_applied, CAST(0 AS SIGNED) AS contribution_version
FROM t_cost_budget_settlement s
LEFT JOIN t_cost_reconciliation_case c ON c.event_id=s.event_id AND c.tenant_id=s.tenant_id
    AND c.request_id=s.request_id AND c.source=s.source
WHERE s.tenant_id=#{tenantId} AND s.request_started_at >= #{start} AND s.request_started_at < #{end}
  AND (c.id IS NULL OR NOT EXISTS (
      SELECT 1 FROM t_cost_reconciliation_adjustment a WHERE a.case_id=c.id
  ))

    AND s.api_key_id=#{keyId}


    AND s.service_id=#{serviceId}


    AND (s.request_started_at > #{after.requestStartedAt}
         OR (s.request_started_at=#{after.requestStartedAt} AND s.event_id > #{after.eventId}))

UNION ALL
SELECT c.event_id, c.tenant_id, c.user_id, c.api_key_id, a.service_id, c.source, a.operation,
       c.request_id, c.request_started_at, a.cost_status, a.cost_fen, 1, a.version
FROM t_cost_reconciliation_case c
JOIN t_cost_reconciliation_adjustment a ON a.case_id=c.id
    AND a.version=(
        SELECT latest.version FROM t_cost_reconciliation_adjustment latest
        WHERE latest.case_id=c.id ORDER BY latest.version DESC LIMIT 1
    )
WHERE c.tenant_id=#{tenantId} AND c.request_started_at >= #{start} AND c.request_started_at < #{end}

    AND c.api_key_id=#{keyId}



    AND a.service_id=#{serviceId}


    AND (c.request_started_at > #{after.requestStartedAt}
         OR (c.request_started_at=#{after.requestStartedAt} AND c.event_id > #{after.eventId}))
